//! Rust port of TPTBox.core.np_utils.euclidean_distance_transform (TPTBox/core/np_utils.py), generated by fast-anything.
//! Check it with:  fast-anything verify TPTBox.core.np_utils.euclidean_distance_transform
//!
//! Reproduces `scipy.ndimage.distance_transform_edt`: the feature transform of scipy's C code
//! (`_ComputeFT` / `_VoronoiFT`, separable Voronoi passes along axis 0, 1, 2, ...) with its float
//! operations in the same order, so ties go to the same site, and the distances the way scipy's
//! Python computes them from the feature transform (int32 differences -> float64 -> times sampling
//! -> squared -> summed in axis order -> sqrt). Results are bit-identical.
//!
//! With finite sampling (`feature_transform_fast`) the passes skip the feature components that
//! scipy's scheme fixes structurally and process lines in blocks for row-by-row memory access;
//! pass 0 reduces to a nearest-background scan for ordinary spacings (`Pass0`). Non-finite
//! sampling runs the literal scheme (`feature_transform`). Single-threaded; the GIL is released.

use numpy::ndarray::{Array, IxDyn};
use numpy::{IntoPyArray, PyArrayDyn, PyArrayMethods, PyReadonlyArray1, PyUntypedArrayMethods};
use pyo3::exceptions::{PyRuntimeError, PyTypeError, PyValueError};
use pyo3::prelude::*;
use pyo3::types::{PyDict, PyList, PyString};

/// scipy's `_normalize_sequence(sampling, rank)` followed by `np.asarray(..., dtype=np.float64)`.
/// The C code reads the first `rank` doubles of the (contiguous) result.
fn normalize_sampling(py: Python<'_>, sampling: &Bound<'_, PyAny>, rank: usize) -> PyResult<Vec<f64>> {
    let np = py.import("numpy")?;
    let iterable = !sampling.is_instance_of::<PyString>() && np.call_method1("iterable", (sampling,))?.is_truthy()?;
    let normalized = if iterable {
        let list = py.import("builtins")?.getattr("list")?.call1((sampling,))?;
        if list.len()? != rank {
            return Err(PyRuntimeError::new_err("sequence argument must have length equal to input rank"));
        }
        list
    } else {
        PyList::new(py, std::iter::repeat_n(sampling, rank))?.into_any()
    };
    let kwargs = PyDict::new(py);
    kwargs.set_item("dtype", np.getattr("float64")?)?;
    let arr = np.call_method("ascontiguousarray", (normalized,), Some(&kwargs))?.call_method0("ravel")?;
    let arr: PyReadonlyArray1<'_, f64> = arr.extract()?;
    let values = arr.as_slice()?;
    if values.len() < rank {
        return Err(PyRuntimeError::new_err("sequence argument must have length equal to input rank"));
    }
    Ok(values[..rank].to_vec())
}

/// Scratch space for one line of a pass, reused across lines.
struct Line {
    /// feature coordinates of each site (rank values per site)
    feat: Vec<i32>,
    /// the site's coordinate along the pass axis, as a double
    fd: Vec<f64>,
    /// sum of the squared off-axis terms, in axis order (scipy's wR/uR/vR)
    w: Vec<f64>,
    /// sum of the squared terms of the axes before the pass axis (start of scipy's delta)
    pre: Vec<f64>,
    /// squared terms of the axes after the pass axis, added after the on-axis term
    post: Vec<f64>,
    /// Voronoi stack of site indices
    g: Vec<usize>,
}

/// One `_VoronoiFT` pass along axis `d` over every line of `ft` (layout: rank planes of `n` voxels).
fn pass(ft: &mut [i32], shape: &[usize], n: usize, d: usize, s: &[f64], line: &mut Line) {
    let rank = shape.len();
    let len = shape[d];
    let stride: usize = shape[d + 1..].iter().product();
    let outer: usize = shape[..d].iter().product();
    let npost = rank - 1 - d;
    let sd = s[d];
    let mut co = vec![0i64; rank];
    for o in 0..outer {
        let mut rem = o;
        for jj in (0..d).rev() {
            co[jj] = (rem % shape[jj]) as i64;
            rem /= shape[jj];
        }
        for i in 0..stride {
            let mut rem = i;
            for jj in (d + 1..rank).rev() {
                co[jj] = (rem % shape[jj]) as i64;
                rem /= shape[jj];
            }
            let start = o * len * stride + i;
            // gather the sites (voxels holding a feature) with their precomputed terms
            line.feat.clear();
            line.fd.clear();
            line.w.clear();
            line.pre.clear();
            line.post.clear();
            for ii in 0..len {
                let lin = start + ii * stride;
                if ft[lin] < 0 {
                    continue;
                }
                let mut w = 0.0f64;
                let mut pre = 0.0f64;
                for jj in 0..rank {
                    let f = ft[jj * n + lin];
                    line.feat.push(f);
                    if jj == d {
                        continue;
                    }
                    let t = (i64::from(f) - co[jj]) as f64 * s[jj];
                    let sq = t * t;
                    w += sq;
                    if jj < d {
                        pre += sq;
                    } else {
                        line.post.push(sq);
                    }
                }
                line.fd.push(f64::from(ft[d * n + lin]));
                line.w.push(w);
                line.pre.push(pre);
            }
            let nsite = line.w.len();
            if nsite == 0 {
                continue; // scipy leaves lines without a feature untouched
            }
            // Voronoi stack
            line.g.clear();
            for k in 0..nsite {
                let fd = line.fd[k];
                let w_r = line.w[k];
                while line.g.len() >= 2 {
                    let idx1 = line.g[line.g.len() - 1];
                    let idx2 = line.g[line.g.len() - 2];
                    let f1 = line.fd[idx1];
                    let a = (f1 - line.fd[idx2]) * sd;
                    let b = (fd - f1) * sd;
                    let c = a + b;
                    let u_r = line.w[idx2];
                    let v_r = line.w[idx1];
                    if c * v_r - b * u_r - a * w_r - a * b * c <= 0.0 {
                        break;
                    }
                    line.g.pop();
                }
                line.g.push(k);
            }
            // sweep: nearest site per voxel, ties to the earlier one
            let delta = |site: usize, ii: usize| -> f64 {
                let t = (i64::from(line.feat[site * rank + d]) - ii as i64) as f64 * sd;
                let mut acc = line.pre[site] + t * t;
                for p in &line.post[site * npost..(site + 1) * npost] {
                    acc += p;
                }
                acc
            };
            let maxl = line.g.len() - 1;
            let mut l = 0usize;
            for ii in 0..len {
                let mut delta1 = delta(line.g[l], ii);
                while l < maxl {
                    let delta2 = delta(line.g[l + 1], ii);
                    if delta1 <= delta2 {
                        break;
                    }
                    delta1 = delta2;
                    l += 1;
                }
                let site = line.g[l];
                let lin = start + ii * stride;
                for jj in 0..rank {
                    ft[jj * n + lin] = line.feat[site * rank + jj];
                }
            }
        }
    }
}

/// Feature transform of `mask` (true = foreground), scipy's int32 layout `(rank, *shape)`.
fn feature_transform(mask: &[bool], shape: &[usize], s: &[f64]) -> Vec<i32> {
    let rank = shape.len();
    let n = mask.len();
    let mut ft = vec![0i32; rank * n];
    // init: background voxels hold their own index, foreground ones -1 in component 0
    let mut co = vec![0usize; rank];
    for (lin, &m) in mask.iter().enumerate() {
        if m {
            ft[lin] = -1;
        } else {
            for jj in 0..rank {
                ft[jj * n + lin] = co[jj] as i32;
            }
        }
        for jj in (0..rank).rev() {
            co[jj] += 1;
            if co[jj] < shape[jj] {
                break;
            }
            co[jj] = 0;
        }
    }
    let longest = shape.iter().copied().max().unwrap_or(0);
    let mut line = Line {
        feat: Vec::with_capacity(longest * rank),
        fd: Vec::with_capacity(longest),
        w: Vec::with_capacity(longest),
        pre: Vec::with_capacity(longest),
        post: Vec::with_capacity(longest * rank),
        g: Vec::with_capacity(longest),
    };
    for d in 0..rank {
        pass(&mut ft, shape, n, d, s, &mut line);
    }
    ft
}

/// Per-line scratch of the fast path, sized for the longest axis and reused across lines.
struct Sites {
    /// position of each site along the line (scipy's f[d], which equals the position)
    pos: Vec<f64>,
    /// the same position as stored in the feature transform
    pos_i: Vec<i32>,
    /// sum of the squared terms of the axes before the pass axis (scipy's wR and delta prefix)
    pre: Vec<f64>,
    /// the site's feature components before the pass axis (`d` values per site)
    comps: Vec<i32>,
    /// Voronoi stack: site index, position and prefix of each entry
    g: Vec<u32>,
    g_pos: Vec<f64>,
    g_pre: Vec<f64>,
    /// nearest site per voxel of the line
    assign: Vec<u32>,
}

impl Sites {
    fn new(longest: usize, rank: usize) -> Self {
        Sites {
            pos: vec![0.0; longest],
            pos_i: vec![0; longest],
            pre: vec![0.0; longest],
            comps: vec![0; longest * rank],
            g: Vec::with_capacity(longest),
            g_pos: Vec::with_capacity(longest),
            g_pre: Vec::with_capacity(longest),
            assign: vec![0; longest],
        }
    }

    /// scipy's `_VoronoiFT` on the `m` gathered sites of a line of `len` voxels: the stack, then the
    /// sweep that gives each voxel the nearest site (ties to the earlier one) in `assign`.
    fn voronoi(&mut self, m: usize, len: usize, sd: f64) {
        assert!(m >= 1 && m <= self.pos.len() && len <= self.assign.len());
        self.g.resize(m, 0);
        self.g_pos.resize(m, 0.0);
        self.g_pre.resize(m, 0.0);
        let (g, gp, gq) = (&mut self.g[..m], &mut self.g_pos[..m], &mut self.g_pre[..m]);
        let (pos, pre) = (&self.pos[..m], &self.pre[..m]);
        let mut top = 0usize; // stack size
        for k in 0..m {
            let fd = pos[k];
            let w_r = pre[k];
            // SAFETY: top <= k < m, so every index below is in bounds
            unsafe {
                while top >= 2 {
                    let f1 = *gp.get_unchecked(top - 1);
                    let a = (f1 - *gp.get_unchecked(top - 2)) * sd;
                    let b = (fd - f1) * sd;
                    let c = a + b;
                    let u_r = *gq.get_unchecked(top - 2);
                    let v_r = *gq.get_unchecked(top - 1);
                    if c * v_r - b * u_r - a * w_r - a * b * c <= 0.0 {
                        break;
                    }
                    top -= 1;
                }
                *g.get_unchecked_mut(top) = k as u32;
                *gp.get_unchecked_mut(top) = fd;
                *gq.get_unchecked_mut(top) = w_r;
            }
            top += 1;
        }
        let maxl = top - 1;
        let mut l = 0usize;
        for (ii, out) in self.assign[..len].iter_mut().enumerate() {
            let x = ii as f64;
            // SAFETY: l <= maxl < top <= m
            unsafe {
                // (f - ii) is exact in doubles, so this is scipy's (double)(f - ii) * sampling
                let t = (*gp.get_unchecked(l) - x) * sd;
                let mut delta1 = *gq.get_unchecked(l) + t * t;
                while l < maxl {
                    let t2 = (*gp.get_unchecked(l + 1) - x) * sd;
                    let delta2 = *gq.get_unchecked(l + 1) + t2 * t2;
                    if delta1 <= delta2 {
                        break;
                    }
                    delta1 = delta2;
                    l += 1;
                }
                *out = *g.get_unchecked(l);
            }
        }
    }
}

/// Gathers the sites of line `b` of a block (components `0..D` of scipy's feature transform in
/// `local_in`, `[component][position * bw + line]`) into `sites`; returns their number.
#[inline(always)]
fn gather_sites<const D: usize>(sites: &mut Sites, local_in: &[i32], blk: usize, len: usize, bw: usize, b: usize, co: &[i64], s: &[f64]) -> usize {
    let mut m = 0usize;
    for ii in 0..len {
        let idx = ii * bw + b;
        if local_in[idx] < 0 {
            continue;
        }
        let mut pre = 0.0f64;
        for c in 0..D {
            let v = local_in[c * blk + idx];
            sites.comps[m * D + c] = v;
            let t = (i64::from(v) - co[c]) as f64 * s[c];
            pre += t * t;
        }
        sites.pos[m] = ii as f64;
        sites.pos_i[m] = ii as i32;
        sites.pre[m] = pre;
        m += 1;
    }
    m
}

/// Writes the assigned sites of line `b` into `local_out` (components `0..=D`).
#[inline(always)]
fn write_line<const D: usize>(sites: &Sites, local_out: &mut [i32], blk: usize, len: usize, bw: usize, b: usize) {
    for ii in 0..len {
        let k = sites.assign[ii] as usize;
        let idx = ii * bw + b;
        for c in 0..D {
            local_out[c * blk + idx] = sites.comps[k * D + c];
        }
        local_out[D * blk + idx] = sites.pos_i[k];
    }
}

/// How pass 0 can be done without the Voronoi machinery. In pass 0 every site's prefix is 0, so
/// for `sd >= 0` the stack never pops (its test is `-a*b*c <= 0`) and the sweep compares
/// `((p - ii) * sd)^2` only. With `sd == 0` those are all 0 and the sweep never leaves the first
/// site; with `1e-100 <= sd` and `sd * len <= 1e100` they neither under- nor overflow and grow
/// strictly with `|p - ii|`, so the sweep finds the nearest background voxel, ties to the earlier one.
#[derive(Clone, Copy, PartialEq)]
enum Pass0 {
    Generic,
    First,
    Nearest,
}

impl Pass0 {
    fn of(sd: f64, len: usize) -> Self {
        if sd == 0.0 {
            Pass0::First
        } else if sd >= 1e-100 && sd * (len as f64) <= 1e100 {
            Pass0::Nearest
        } else {
            Pass0::Generic
        }
    }
}

/// Pass 0 for a block of `bw` lines in `[position * bw + line]` layout: each voxel's nearest
/// background (false) voxel along the line, or the line's first one, -1 for lines without any.
fn pass0_block(mask: &[bool], out: &mut [i32], len: usize, bw: usize, how: Pass0, scan: &mut [i32]) {
    let scan = &mut scan[..bw];
    scan.fill(-1);
    match how {
        Pass0::First => {
            for ii in (0..len).rev() {
                let row = &mask[ii * bw..(ii + 1) * bw];
                for (f, &m) in scan.iter_mut().zip(row) {
                    if !m {
                        *f = ii as i32;
                    }
                }
            }
            for ii in 0..len {
                out[ii * bw..(ii + 1) * bw].copy_from_slice(scan);
            }
        }
        Pass0::Nearest => {
            // forward: last background voxel at or before ii
            for ii in 0..len {
                let row = &mask[ii * bw..(ii + 1) * bw];
                let o = &mut out[ii * bw..(ii + 1) * bw];
                for ((p, &m), oo) in scan.iter_mut().zip(row).zip(o.iter_mut()) {
                    if !m {
                        *p = ii as i32;
                    }
                    *oo = *p;
                }
            }
            // backward: first background voxel at or after ii, and the nearer of the two
            scan.fill(-1);
            for ii in (0..len).rev() {
                let row = &mask[ii * bw..(ii + 1) * bw];
                let o = &mut out[ii * bw..(ii + 1) * bw];
                let i = ii as i32;
                for ((q, &m), oo) in scan.iter_mut().zip(row).zip(o.iter_mut()) {
                    if !m {
                        *q = i;
                    }
                    let p = *oo;
                    *oo = if p < 0 || (*q >= 0 && *q - i < i - p) { *q } else { p };
                }
            }
        }
        Pass0::Generic => unreachable!(),
    }
}

/// Feature transform for finite sampling. Identical to `feature_transform`, but uses two facts of
/// scipy's separable scheme instead of storing and reading them: in pass `d` a site's component `d`
/// is its own position on the line, and its components after `d` are the line's coordinates, so
/// their terms are `(0 * s)^2 = +0` and drop out of every sum. Pass `d` therefore reads components
/// `0..d` and writes `0..=d`; the last pass writes every component. Lines are processed in blocks of
/// `bw` neighbours, copied row by row into scratch (layout `[component][position * bw + line]`).
fn feature_transform_fast(mask: &[bool], shape: &[usize], s: &[f64]) -> Vec<i32> {
    let rank = shape.len();
    let n = mask.len();
    let mut ft = vec![0i32; rank * n];
    if n == 0 {
        return ft;
    }
    let longest = shape.iter().copied().max().unwrap_or(0);
    let mut sites = Sites::new(longest, rank);
    let mut co = vec![0i64; rank];
    for d in 0..rank {
        let len = shape[d];
        let stride: usize = shape[d + 1..].iter().product();
        let outer: usize = shape[..d].iter().product();
        // a whole len x stride slab when it is small, else blocks of 64 lines
        let bsz = if len * stride <= 32768 { stride } else { stride.min(64) };
        let blk = bsz * len;
        let sd = s[d];
        let mut local_mask = vec![false; if d == 0 { blk } else { 0 }];
        let mut local_in = vec![0i32; d * blk];
        let mut local_out = vec![0i32; (d + 1) * blk];
        let pass0_scan = if d == 0 { Pass0::of(sd, len) } else { Pass0::Generic };
        let mut scan = vec![0i32; if d == 0 { bsz } else { 0 }];
        for o in 0..outer {
            let mut rem = o;
            for jj in (0..d).rev() {
                co[jj] = (rem % shape[jj]) as i64;
                rem /= shape[jj];
            }
            let obase = o * len * stride;
            let mut i0 = 0;
            while i0 < stride {
                let bw = bsz.min(stride - i0);
                let base = obase + i0;
                // gather rows
                if bw == stride {
                    if d == 0 {
                        local_mask[..len * bw].copy_from_slice(&mask[base..base + len * bw]);
                    }
                    for c in 0..d {
                        local_in[c * blk..c * blk + len * bw].copy_from_slice(&ft[c * n + base..c * n + base + len * bw]);
                    }
                } else {
                    for ii in 0..len {
                        let row = base + ii * stride;
                        if d == 0 {
                            local_mask[ii * bw..(ii + 1) * bw].copy_from_slice(&mask[row..row + bw]);
                        }
                        for c in 0..d {
                            local_in[c * blk + ii * bw..c * blk + (ii + 1) * bw].copy_from_slice(&ft[c * n + row..c * n + row + bw]);
                        }
                    }
                }
                if d == 0 && pass0_scan != Pass0::Generic {
                    pass0_block(&local_mask[..len * bw], &mut local_out[..len * bw], len, bw, pass0_scan, &mut scan);
                } else {
                for b in 0..bw {
                    if d == 1 || d == 2 {
                        let m = if d == 1 {
                            gather_sites::<1>(&mut sites, &local_in, blk, len, bw, b, &co, s)
                        } else {
                            gather_sites::<2>(&mut sites, &local_in, blk, len, bw, b, &co, s)
                        };
                        if m > 0 {
                            sites.voronoi(m, len, sd);
                            if d == 1 {
                                write_line::<1>(&sites, &mut local_out, blk, len, bw, b);
                            } else {
                                write_line::<2>(&sites, &mut local_out, blk, len, bw, b);
                            }
                            continue;
                        }
                    }
                    // sites of this line
                    let mut m = 0usize;
                    for ii in 0..len {
                        let idx = ii * bw + b;
                        let site = if d == 0 { !local_mask[idx] } else { local_in[idx] >= 0 };
                        if !site {
                            continue;
                        }
                        let mut pre = 0.0f64;
                        for c in 0..d {
                            let v = local_in[c * blk + idx];
                            sites.comps[m * d + c] = v;
                            let t = (i64::from(v) - co[c]) as f64 * s[c];
                            pre += t * t;
                        }
                        sites.pos[m] = ii as f64;
                        sites.pos_i[m] = ii as i32;
                        sites.pre[m] = pre;
                        m += 1;
                    }
                    if m == 0 {
                        // untouched line: every voxel still holds scipy's (-1, 0, ...)
                        for ii in 0..len {
                            local_out[ii * bw + b] = -1;
                            for c in 1..=d {
                                local_out[c * blk + ii * bw + b] = 0;
                            }
                        }
                        continue;
                    }
                    sites.voronoi(m, len, sd);
                    for ii in 0..len {
                        let k = sites.assign[ii] as usize;
                        let idx = ii * bw + b;
                        for c in 0..d {
                            local_out[c * blk + idx] = sites.comps[k * d + c];
                        }
                        local_out[d * blk + idx] = sites.pos_i[k];
                    }
                }
                }
                // scatter rows back
                if bw == stride {
                    for c in 0..=d {
                        ft[c * n + base..c * n + base + len * bw].copy_from_slice(&local_out[c * blk..c * blk + len * bw]);
                    }
                } else {
                    for ii in 0..len {
                        let row = base + ii * stride;
                        for c in 0..=d {
                            ft[c * n + row..c * n + row + bw].copy_from_slice(&local_out[c * blk + ii * bw..c * blk + (ii + 1) * bw]);
                        }
                    }
                }
                i0 += bw;
            }
        }
    }
    ft
}

/// scipy's distances from the feature transform (`dt = ft - indices` in int32, to float64, times
/// sampling when given, squared, summed over the components in order, sqrt), one row at a time.
fn distances(ft: &[i32], shape: &[usize], s: Option<&[f64]>) -> Vec<f64> {
    let rank = shape.len();
    let n: usize = shape.iter().product();
    let mut out = vec![0.0f64; n];
    if n == 0 {
        return out;
    }
    let last = shape[rank - 1];
    let mut co = vec![0i32; rank];
    for (r, o) in out.chunks_exact_mut(last).enumerate() {
        let base = r * last;
        for jj in 0..rank {
            let plane = &ft[jj * n + base..jj * n + base + last];
            let along = jj == rank - 1;
            let c = co[jj];
            // the four cases as separate loops, so each one vectorises
            macro_rules! accumulate {
                ($x:expr) => {
                    if jj == 0 {
                        for (k, (v, &f)) in o.iter_mut().zip(plane).enumerate() {
                            let x = $x(k, f);
                            *v = x * x;
                        }
                    } else {
                        for (k, (v, &f)) in o.iter_mut().zip(plane).enumerate() {
                            let x = $x(k, f);
                            *v += x * x;
                        }
                    }
                };
            }
            match (s, along) {
                (None, true) => accumulate!(|k: usize, f: i32| f64::from(f.wrapping_sub(k as i32))),
                (None, false) => accumulate!(|_k: usize, f: i32| f64::from(f.wrapping_sub(c))),
                (Some(s), true) => {
                    let sj = s[jj];
                    accumulate!(|k: usize, f: i32| f64::from(f.wrapping_sub(k as i32)) * sj)
                }
                (Some(s), false) => {
                    let sj = s[jj];
                    accumulate!(|_k: usize, f: i32| f64::from(f.wrapping_sub(c)) * sj)
                }
            }
        }
        for v in o.iter_mut() {
            *v = v.sqrt();
        }
        for jj in (0..rank - 1).rev() {
            co[jj] += 1;
            if (co[jj] as usize) < shape[jj] {
                break;
            }
            co[jj] = 0;
        }
    }
    out
}

type Outputs = (Option<Py<PyArrayDyn<f64>>>, Option<Py<PyArrayDyn<i32>>>);

/// A flag taken by truthiness, as the Python `if return_distances ...` does.
struct Truthy(bool);

impl<'a, 'py> FromPyObject<'a, 'py> for Truthy {
    type Error = PyErr;
    fn extract(obj: Borrowed<'a, 'py, PyAny>) -> Result<Self, Self::Error> {
        Ok(Truthy(obj.is_truthy()?))
    }
}

#[pyfunction]
#[pyo3(signature = (mask, sampling = None, return_distances = Truthy(true), return_indices = Truthy(false)))]
fn euclidean_distance_transform(
    py: Python<'_>,
    mask: &Bound<'_, PyAny>,
    sampling: Option<&Bound<'_, PyAny>>,
    return_distances: Truthy,
    return_indices: Truthy,
) -> PyResult<Outputs> {
    let Ok(mask) = mask.cast::<PyArrayDyn<bool>>() else {
        let dtype = mask.getattr("dtype").map(|d| d.to_string()).unwrap_or_else(|_| "?".into());
        return Err(PyTypeError::new_err(format!("expected a boolean mask, got {dtype}")));
    };
    if mask.ndim() == 0 {
        return Err(PyValueError::new_err("expected a mask with at least one dimension"));
    }
    let (want_dist, want_idx) = (return_distances.0, return_indices.0);
    if !want_dist && !want_idx {
        return Err(PyRuntimeError::new_err("at least one of return_distances/return_indices must be True"));
    }
    let shape: Vec<usize> = mask.shape().to_vec();
    let rank = shape.len();
    let samp = match sampling {
        Some(s) if !s.is_none() => Some(normalize_sampling(py, s, rank)?),
        _ => None,
    };
    let ro = mask.try_readonly()?;
    let owned;
    // as_slice also accepts Fortran order, whose memory order is not the logical order
    let flat: &[bool] = match ro.as_slice() {
        Ok(sl) if mask.is_c_contiguous() => sl,
        _ => {
            owned = ro.as_array().iter().copied().collect::<Vec<bool>>();
            &owned
        }
    };
    let (dist, ft) = py.detach(|| {
        let ones = vec![1.0f64; rank];
        let s = samp.as_deref().unwrap_or(&ones);
        // non-finite sampling makes the dropped terms NaN (0 * inf), so it needs the full scheme
        let ft = if s.iter().all(|x| x.is_finite()) { feature_transform_fast(flat, &shape, s) } else { feature_transform(flat, &shape, s) };
        let dist = want_dist.then(|| distances(&ft, &shape, samp.as_deref()));
        (dist, ft)
    });
    let dist = match dist {
        Some(v) => Some(Array::from_shape_vec(IxDyn(&shape), v).expect("shape").into_pyarray(py).unbind()),
        None => None,
    };
    let idx = if want_idx {
        let mut ishape = Vec::with_capacity(rank + 1);
        ishape.push(rank);
        ishape.extend_from_slice(&shape);
        Some(Array::from_shape_vec(IxDyn(&ishape), ft).expect("shape").into_pyarray(py).unbind())
    } else {
        None
    };
    Ok((dist, idx))
}

#[pymodule]
fn fa_tptbox_core_np_utils_euclidean_distance_transform(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(euclidean_distance_transform, m)?)?;
    Ok(())
}
